function unlockedRewardLevel(){return friendshipLevel()}
function nextGrowthReward(){
 const lv=friendshipLevel(),next=growthRewards.find(r=>r.level>lv);
 return next||null;
}
function growthAccessory(lv){
 if(lv>=10)return "👑";
 if(lv>=8)return "✨";
 if(lv>=5)return "🎀";
 return "";
}
