function strokeFeatures(strokes){
  const clean=strokes.filter(st=>st&&st.length>1),pts=clean.flat();
  if(!pts.length)return{n:0,w:0,h:0,verticals:0,horizontals:0,longVerticalNearCenter:false};
  const xs=pts.map(p=>p.x),ys=pts.map(p=>p.y),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
  const w=Math.max(1,maxX-minX),h=Math.max(1,maxY-minY),cx=(minX+maxX)/2;
  let verticals=0,horizontals=0,longVerticalNearCenter=false;
  for(const st of clean){
    const a=st[0],b=st[st.length-1],dx=Math.abs(b.x-a.x),dy=Math.abs(b.y-a.y);
    const sx=st.map(p=>p.x),sy=st.map(p=>p.y),sw=Math.max(...sx)-Math.min(...sx),sh=Math.max(...sy)-Math.min(...sy);
    if(sh>sw*1.45)verticals++;
    if(sw>sh*1.45)horizontals++;
    const scx=(Math.min(...sx)+Math.max(...sx))/2;
    if(sh>h*.62 && Math.abs(scx-cx)<w*.22)longVerticalNearCenter=true;
  }
  return{n:clean.length,w,h,verticals,horizontals,longVerticalNearCenter};
}
function expectedAwareFallback(box,candidates){
  const got=candidates[0]||null,n=box.strokes.length,f=strokeFeatures(box.strokes);
  if(box.expected==="守"&&got==="尻"&&n>=5&&n<=9)return true;
  // iPadの指書きで「申」が候補0件になりやすいケースを構造で救済。
  // 何でも正解にしないよう、画数・中央の長い縦線・横線のまとまりを同時に要求する。
  if(box.expected==="申"&&candidates.length===0&&f.n>=4&&f.n<=7&&f.longVerticalNearCenter&&f.horizontals>=2)return true;
  return false;
}
function recognizeWithNormalization(expected,strokes,size,boxSize,preserveAspect=false){
  const c=document.createElement("canvas"),id=`tmp_${Math.random().toString(36).slice(2)}`;
  c.id=id;c.width=size;c.height=size;c.style.display="none";document.body.appendChild(c);
  const ctx=c.getContext("2d"),all=strokes.flat();
  if(!all.length){c.remove();return[]}
  const xs=all.map(p=>p.x),ys=all.map(p=>p.y),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
  const w=Math.max(1,maxX-minX),h=Math.max(1,maxY-minY);
  let sx=boxSize/w,sy=boxSize/h;
  if(!preserveAspect){const s=Math.min(sx,sy);sx=s;sy=s}
  const dw=w*sx,dh=h*sy,ox=(size-dw)/2,oy=(size-dh)/2;
  const normalized=strokes.map(st=>st.map(p=>[ox+(p.x-minX)*sx,oy+(p.y-minY)*sy]));
  KanjiCanvas["canvas_"+id]=c;KanjiCanvas["ctx_"+id]=ctx;KanjiCanvas["w_"+id]=size;KanjiCanvas["h_"+id]=size;KanjiCanvas["recordedPattern_"+id]=normalized;
  let raw="";try{raw=KanjiCanvas.recognize(id)||""}catch(e){console.error(e)}
  c.remove();
  return [...raw.replace(/\s+/g,"")];
}




// v5.1 — 全漢字共通・オフライン字形参照エンジン
// すでに読み込まれている KanjiCanvas.refPatterns を直接利用する。
// refPatterns の各要素は [文字, 正しい画数, 正字の参照ストローク]。
// 外部SVG取得に依存しないため、通信失敗で「赤い○が出ない」問題を防ぐ。

function getRefPattern(ch){
  if(!window.KanjiCanvas || !Array.isArray(KanjiCanvas.refPatterns)) return null;
  return KanjiCanvas.refPatterns.find(p=>Array.isArray(p) && p[0]===ch) || null;
}

function normalizeStrokeSet(strokes){
  const clean=(strokes||[]).filter(st=>st&&st.length>1);
  const pts=clean.flat();
  if(!pts.length)return {strokes:[],box:null};
  const xs=pts.map(p=>Number(p.x ?? p[0])), ys=pts.map(p=>Number(p.y ?? p[1]));
  const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
  const w=Math.max(1,maxX-minX),h=Math.max(1,maxY-minY);
  const norm=clean.map(st=>st.map(p=>{
    const x=Number(p.x ?? p[0]),y=Number(p.y ?? p[1]);
    return {x:(x-minX)/w,y:(y-minY)/h};
  }));
  return {strokes:norm,box:{minX,minY,w,h}};
}

function resampleStroke(st,n=20){
  if(!st||st.length<2)return[];
  const pts=st.map(p=>({x:Number(p.x ?? p[0]),y:Number(p.y ?? p[1])}));
  const cum=[0]; let total=0;
  for(let i=1;i<pts.length;i++){
    total+=Math.hypot(pts[i].x-pts[i-1].x,pts[i].y-pts[i-1].y);
    cum.push(total);
  }
  if(total<=0)return Array.from({length:n},()=>({...pts[0]}));
  const out=[];
  for(let k=0;k<n;k++){
    const t=total*(k/(n-1));
    let i=1; while(i<cum.length&&cum[i]<t)i++;
    i=Math.min(i,cum.length-1);
    const a=pts[i-1],b=pts[i],den=Math.max(1e-8,cum[i]-cum[i-1]);
    const u=(t-cum[i-1])/den;
    out.push({x:a.x+(b.x-a.x)*u,y:a.y+(b.y-a.y)*u});
  }
  return out;
}

function strokeDescriptor(st){
  const rs=resampleStroke(st,20);
  if(!rs.length)return null;
  const xs=rs.map(p=>p.x),ys=rs.map(p=>p.y);
  const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
  let len=0;for(let i=1;i<rs.length;i++)len+=Math.hypot(rs[i].x-rs[i-1].x,rs[i].y-rs[i-1].y);
  const a=rs[0],b=rs[rs.length-1];
  return{
    rs,cx:(minX+maxX)/2,cy:(minY+maxY)/2,w:maxX-minX,h:maxY-minY,len,
    dx:b.x-a.x,dy:b.y-a.y
  };
}

function strokeDistance(a,b){
  if(!a||!b)return 999;
  const direct=a.rs.reduce((s,p,i)=>s+Math.hypot(p.x-b.rs[i].x,p.y-b.rs[i].y),0)/a.rs.length;
  const reverse=a.rs.reduce((s,p,i)=>s+Math.hypot(p.x-b.rs[b.rs.length-1-i].x,p.y-b.rs[b.rs.length-1-i].y),0)/a.rs.length;
  const shape=Math.min(direct,reverse);
  const center=Math.hypot(a.cx-b.cx,a.cy-b.cy);
  const len=Math.abs(a.len-b.len);
  return shape*.55+center*.30+len*.15;
}

function bestStrokeAssignment(userStrokes,refStrokes){
  const u=userStrokes.map(strokeDescriptor),r=refStrokes.map(strokeDescriptor);
  const pairs=[];
  for(let i=0;i<u.length;i++)for(let j=0;j<r.length;j++)pairs.push({i,j,d:strokeDistance(u[i],r[j])});
  pairs.sort((a,b)=>a.d-b.d);
  const usedU=new Set(),usedR=new Set(),matches=[];
  for(const p of pairs){
    if(usedU.has(p.i)||usedR.has(p.j))continue;
    usedU.add(p.i);usedR.add(p.j);matches.push(p);
  }
  return{
    matches,u,r,
    unmatchedUser:u.map((_,i)=>i).filter(i=>!usedU.has(i)),
    unmatchedRef:r.map((_,i)=>i).filter(i=>!usedR.has(i))
  };
}

function referenceGuide(refStroke,strokeNo,kind="missing"){
  const d=strokeDescriptor(refStroke);
  const pos={x:d?.cx??.5,y:d?.cy??.5,normalized:true,strokeNo};
  if(kind==="missing"){
    return{...pos,msg:`${strokeNo}画目がありません。赤い○の位置に、お手本どおりの線を書こう。`};
  }
  return{...pos,msg:`${strokeNo}画目の位置・向き・長さがお手本と大きくちがいます。赤い○の線を見直そう。`};
}

function inspectAgainstBuiltInReference(expected,strokes){
  const ref=getRefPattern(expected);
  if(!ref || !Array.isArray(ref[2]) || !ref[2].length){
    return{available:false,feedbackGuides:[]};
  }

  const expectedCount=Number(ref[1])||ref[2].length;
  const userClean=(strokes||[]).filter(s=>s&&s.length>1);
  const actualCount=userClean.length;
  const userNorm=normalizeStrokeSet(userClean).strokes;
  const refNorm=normalizeStrokeSet(ref[2]).strokes;

  const assignment=bestStrokeAssignment(userNorm,refNorm);

  if(actualCount<expectedCount){
    let missing=assignment.unmatchedRef.slice();
    // ref[1] と参照ストローク数がずれるデータでも、足りない個数は保証する。
    const need=expectedCount-actualCount;
    if(missing.length<need){
      const used=new Set(missing);
      for(let j=refNorm.length-1;j>=0&&missing.length<need;j--)if(!used.has(j))missing.push(j);
    }
    const guides=missing.slice(0,3).map(j=>referenceGuide(refNorm[j],j+1,"missing"));
    return{
      available:true,pass:false,reason:"missing-strokes",
      expectedCount,actualCount,missingCount:need,extraCount:0,
      feedbackGuides:guides
    };
  }

  if(actualCount>expectedCount){
    const extra=actualCount-expectedCount;
    const guides=assignment.unmatchedUser.slice(0,2).map(i=>{
      const d=assignment.u[i];
      return{
        x:d?.cx??.5,y:d?.cy??.5,normalized:true,
        msg:`この線は余分な可能性があります。お手本の${expectedCount}画とくらべよう。`
      };
    });
    if(!guides.length)guides.push({x:.5,y:.5,normalized:true,msg:`線が${extra}画多いです。余分な線を見直そう。`});
    return{
      available:true,pass:false,reason:"extra-strokes",
      expectedCount,actualCount,missingCount:0,extraCount:extra,
      feedbackGuides:guides
    };
  }

  // 画数が同じでも、参照字形から大きく外れる画を具体的に示す。
  const bad=assignment.matches.filter(m=>m.d>.23).sort((a,b)=>b.d-a.d);
  if(bad.length){
    const guides=bad.slice(0,2).map(m=>referenceGuide(refNorm[m.j],m.j+1,"shape"));
    return{
      available:true,pass:false,reason:"shape-mismatch",
      expectedCount,actualCount,missingCount:0,extraCount:0,
      feedbackGuides:guides,worstDistance:bad[0].d
    };
  }

  return{
    available:true,pass:true,reason:"reference-ok",
    expectedCount,actualCount,missingCount:0,extraCount:0,feedbackGuides:[]
  };
}

function fallbackGuidesFromUserInk(strokes){
  const clean=(strokes||[]).filter(s=>s&&s.length>1);
  if(!clean.length)return[];
  const norm=normalizeStrokeSet(clean).strokes;
  const ds=norm.map((st,i)=>({...strokeDescriptor(st),i})).filter(Boolean);
  if(!ds.length)return[];
  const suspicious=ds.sort((a,b)=>{
    const sa=Math.abs(a.cx-.5)+Math.abs(a.cy-.5)+Math.max(0,.10-a.len)*2;
    const sb=Math.abs(b.cx-.5)+Math.abs(b.cy-.5)+Math.max(0,.10-b.len)*2;
    return sb-sa;
  })[0];
  return[{
    x:suspicious.cx,y:suspicious.cy,normalized:true,
    msg:"この線の位置・向き・長さを、お手本とくらべて見直そう。"
  }];
}

function kanaReferenceAudit(expected,strokes){
  const ref=getRefPattern(expected);
  const clean=(strokes||[]).filter(s=>s&&s.length>1);
  if(!clean.length)return{available:!!ref,pass:false,score:999};

  // ひらがなも参照パターンがあれば、文字認識と字形距離の両方で確認する。
  if(ref&&Array.isArray(ref[2])&&ref[2].length){
    const u=normalizeStrokeSet(clean).strokes;
    const r=normalizeStrokeSet(ref[2]).strokes;
    const a=bestStrokeAssignment(u,r);
    const mean=a.matches.length?a.matches.reduce((s,m)=>s+m.d,0)/a.matches.length:999;
    const countDiff=Math.abs(clean.length-(Number(ref[1])||r.length));
    return{available:true,pass:countDiff<=1&&mean<.34,score:mean,countDiff};
  }
  return{available:false,pass:false,score:999};
}

async function kanaRecognizeExact(expected,strokes){
  if(!strokes?.flat().length)return{ok:false,excellent:false,unknown:true,got:null,mode:"kana-empty"};
  const passes=[
    recognizeWithNormalization(expected,strokes,320,205,false),
    recognizeWithNormalization(expected,strokes,320,230,false),
    recognizeWithNormalization(expected,strokes,320,250,false),
    recognizeWithNormalization(expected,strokes,320,275,false),
    recognizeWithNormalization(expected,strokes,320,300,false),
    recognizeWithNormalization(expected,strokes,320,250,true)
  ];
  const tops=passes.map(p=>p[0]||null);
  const topExact=tops.filter(x=>x===expected).length;
  const top5=passes.filter(p=>p.slice(0,5).includes(expected)).length;
  const top10=passes.filter(p=>p.slice(0,10).includes(expected)).length;
  const refAudit=kanaReferenceAudit(expected,strokes);

  // 送り仮名は漢字より自然な手書きの幅を許容する。
  // 参照字形に近ければ、認識器の第1候補が毎回一致しなくても正解にする。
  const ok = topExact>=1 || top5>=2 || top10>=4 || refAudit.pass;
  return{
    ok,excellent:ok,unknown:!ok,got:ok?expected:(tops.find(Boolean)||null),
    tops,topExactCount:topExact,top5Count:top5,top10Count:top10,refAudit,
    mode:ok?"kana-flexible-correct":"kana-review"
  };
}

function schoolStrictShapeAudit(strokes){
  const clean=(strokes||[]).filter(st=>st&&st.length>1),pts=clean.flat();
  if(!pts.length)return{pass:false,reason:"no-ink",details:[]};
  const xs=pts.map(p=>p.x),ys=pts.map(p=>p.y);
  const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
  const w=Math.max(1,maxX-minX),h=Math.max(1,maxY-minY),span=Math.max(w,h);
  const details=[];
  const ratio=w/h;
  if(ratio<0.42||ratio>2.35)details.push("balance");
  const ms=clean.map((st,i)=>({...strokeMetrics(st),index:i})).filter(Boolean);
  ms.forEach(m=>{
    const rel=m.len/span;
    if(rel<.105)details.push(`tiny:${m.index}`);
    if(rel>2.15)details.push(`wild:${m.index}`);
  });
  if(clean.length>=6){
    const verticals=ms.filter(m=>m.vertical).length,horizontals=ms.filter(m=>m.horizontal).length;
    if(verticals===0||horizontals===0)details.push("stroke-direction");
  }
  return{pass:details.length===0,reason:details[0]||"ok",details,ratio};
}

async function recognizeSingle(expected,strokes,canvasHint){
  if(!window.KanjiCanvas||!Array.isArray(KanjiCanvas.refPatterns)||!KanjiCanvas.refPatterns.length)return{ok:false,unknown:true,got:null};
  if(!strokes.flat().length)return{ok:false,unknown:true,got:null};

  const refAudit=inspectAgainstBuiltInReference(expected,strokes);

  // 不足画・余分な画・大きな字形崩れは、認識結果より優先して不正解＋赤丸指摘。
  if(refAudit.available && !refAudit.pass){
    return{
      ok:false,excellent:false,unknown:false,got:null,
      mode:refAudit.reason,
      referenceAudit:refAudit,
      strokeAudit:refAudit,
      feedbackGuides:refAudit.feedbackGuides||[]
    };
  }

  const passes=[
    recognizeWithNormalization(expected,strokes,320,225,false),
    recognizeWithNormalization(expected,strokes,320,250,false),
    recognizeWithNormalization(expected,strokes,320,275,false),
    recognizeWithNormalization(expected,strokes,320,300,false),
    recognizeWithNormalization(expected,strokes,320,250,true)
  ];
  const tops=passes.map(p=>p[0]||null);
  const topExactCount=tops.filter(ch=>ch===expected).length;
  const candidates=[];
  for(const pass of passes)for(const ch of pass)if(!candidates.includes(ch))candidates.push(ch);
  const shapeAudit=schoolStrictShapeAudit(strokes);
  const got=tops.find(Boolean)||candidates[0]||null;

  const ok=topExactCount>=4 && shapeAudit.pass && (!refAudit.available||refAudit.pass);
  const unknown=!ok && candidates.includes(expected);

  return{
    ok,excellent:ok,unknown,got,
    rank:candidates.indexOf(expected),fallback:false,candidates,tops,topExactCount,
    shapeAudit,referenceAudit:refAudit,
    feedbackGuides:(!ok ? fallbackGuidesFromUserInk(strokes) : []),
    mode:ok?"v51-ref-strict":(unknown?"uncertain":"wrong")
  };
}
function splitStrokesForExpected(strokes,n){
  if(n<=1)return[strokes];
  const items=strokes.map((st,i)=>{const xs=st.map(p=>p.x);return{st,i,min:Math.min(...xs),max:Math.max(...xs),center:(Math.min(...xs)+Math.max(...xs))/2}}).sort((a,b)=>a.center-b.center);
  if(items.length<n)return Array.from({length:n},(_,i)=>i<items.length?[items[i].st]:[]);
  const gaps=[];for(let i=0;i<items.length-1;i++)gaps.push({i,g:items[i+1].min-items[i].max});
  const cuts=new Set(gaps.sort((a,b)=>b.g-a.g).slice(0,n-1).map(x=>x.i));
  const groups=[[]];items.forEach((it,i)=>{groups[groups.length-1].push(it.st);if(cuts.has(i)&&groups.length<n)groups.push([])});
  while(groups.length<n)groups.push([]);return groups;
}
function okuriInkStats(box){
  const strokes=box.strokes.filter(st=>st&&st.length);
  const pts=strokes.flat();
  if(!pts.length)return{hasInk:false,coverage:0,clusters:0};
  const r=box.canvas.getBoundingClientRect();
  const xs=pts.map(p=>p.x),minX=Math.min(...xs),maxX=Math.max(...xs);
  const coverage=r.width>0?(maxX-minX)/r.width:0;
  // Count broad left-to-right writing groups without exposing the answer length in the UI.
  const items=strokes.map(st=>{const a=st.map(p=>p.x);return{min:Math.min(...a),max:Math.max(...a)}}).sort((a,b)=>a.min-b.min);
  const gaps=[];for(let i=0;i<items.length-1;i++){const g=items[i+1].min-items[i].max;if(g>Math.max(18,r.width*.055))gaps.push(g)}
  return{hasInk:true,coverage,clusters:Math.max(1,Math.min(strokes.length,1+gaps.length))};
}
async function recognizeBox(box){
  if(box.type==="kanji")return await recognizeSingle(box.expected,box.strokes,box.canvas);

  const chars=[...box.expected];
  if(chars.length===1){
    return await kanaRecognizeExact(chars[0],box.strokes);
  }

  const groups=splitStrokesForExpected(box.strokes,chars.length);
  const parts=[];
  for(let i=0;i<chars.length;i++)parts.push(await kanaRecognizeExact(chars[i],groups[i]||[]));
  const bad=parts.findIndex(r=>!r.ok);
  if(bad<0)return{ok:true,excellent:parts.every(r=>r.excellent),unknown:false,got:chars.join(""),parts,bad:-1,mode:"kana-exact"};
  return{
    ok:false,excellent:false,unknown:parts.some(r=>r.unknown),
    got:parts.map(r=>r.got||"?").join(""),parts,bad,mode:"kana-review"
  };
}

$("#revealBtn").onclick=()=>{
  const q=state.questions[state.index];
  const a=answerOf(q);
  state.answerRevealed=true;
  const box=$("#revealedAnswer");
  box.innerHTML=`<b>答え：</b><span class="revealedWord">${a}</span><br><span class="small">見たあとは、まねして書いてみよう。</span>`;
  box.classList.remove("hidden");
  $("#revealBtn").disabled=true;
};


function acceptUncertainAnswer(q,results){
  showFeedback("bad","まだ正解にはしていません。","AIの判定に自信がありません。お手本とくらべて、もう一度書き直してみよう。");
  state.questionCompleted=false;
  state.boxes.forEach(b=>{
    b.canvas.classList.remove("lockedCanvas");
    b.clearOne?.classList.remove("hidden");
  });
  $("#undoBtn").disabled=false;
  $("#clearBtn").disabled=false;
  $("#nextBtn").classList.add("hidden");
}
function showThreeTryConfirmation(q,results,bad){
  const f=$("#feedback");f.className="feedback unknown";
  const answer=answerOf(q);
  f.innerHTML=`<b>3回チャレンジしたね！</b><br>赤く光っているマスをAIがうまく読み取れていないかもしれません。<br>自分の書いた字が <span class="revealedWord">${answer}</span> と合っているか、よく見て確認しよう。<div class="uncertainActions"><button id="confirmUnknownBtn" class="primary">○ 合っている（正解にする）</button><button id="rewriteUnknownBtn" class="secondary">✎ もう一度書く</button></div>`;
  onIf("#confirmUnknownBtn","click",()=>acceptUncertainAnswer(q,results));
  onIf("#rewriteUnknownBtn","click",()=>{hideFeedback();state.activeBox=bad;$("#checkBtn").disabled=false});
}
$("#checkBtn").onclick=async()=>{
  if(state.checking||state.questionCompleted)return;state.checking=true;$("#checkBtn").disabled=true;
  $("#aiModal").classList.remove("hidden");
  try{
    const q=state.questions[state.index],results=await Promise.all(state.boxes.map(recognizeBox)),bad=results.findIndex(r=>!r.ok);
    if(bad<0){
      state.boxes.forEach(resetBoxRepairUI);
      const perfect=results.every(r=>r.excellent);
      if(state.answerRevealed){
        showFeedback("ok","書けたね！",`${answerOf(q)} を見ながら練習できたよ。次は見ないで挑戦してみよう。`);
        state.experience+=1;
      }else{
        showFeedback(perfect?"good":"ok","せいかい！",`${answerOf(q)} と正しく書けたよ。`);
        state.points+=2;state.totalEarned+=2;state.experience+=perfect?3:2;
      }
      state.sessionResults[state.index]={help:state.answerRevealed,retries:state.questionRetries};
      syncLearningEvent("question",{questionId:q.id||"",prompt:q.displaySentence||"",answer:answerOf(q),correct:true,retries:state.questionRetries,help:state.answerRevealed,manualConfirm:false,volume:state.volume});
      ensureDaily();state.daily.questions=(state.daily.questions||0)+1;state.records.totalQuestions=(state.records.totalQuestions||0)+1;if(!state.answerRevealed)state.records.totalCorrect=(state.records.totalCorrect||0)+1;if(state.weak[q.targetKanji])state.weak[q.targetKanji]=Math.max(0,state.weak[q.targetKanji]-1);
      state.discovered.add(q.targetKanji);state.questionCompleted=true;
      state.boxes.forEach(b=>b.canvas.classList.add("lockedCanvas"));
      $("#undoBtn").disabled=true;$("#clearBtn").disabled=true;
      persist();renderMotivation();checkNewAnimalUnlocks();$("#nextBtn").classList.remove("hidden");
    }else{
      if(state.questionRetries===0)state.weak[q.targetKanji]=(state.weak[q.targetKanji]||0)+1;state.questionRetries++;persist();renderMotivation();
      markBoxResults(results);
      state.activeBox=bad;const r=results[bad],box=state.boxes[bad];
      const badPositions=results.map((x,i)=>!x.ok?`${i+1}字目`:null).filter(Boolean).join("・");
      const missingResult=results.find(r=>(r?.referenceAudit?.missingCount||r?.strokeAudit?.missingCount)>0);
      const missingText=missingResult
        ? `必要な線が${missingResult.referenceAudit?.missingCount||missingResult.strokeAudit?.missingCount}画足りません。赤い○の場所に、足りない線を書こう。`
        : "";
      if(state.questionRetries>=3){
        showThreeTryConfirmation(q,results,bad);
      }else if(box.type==="okuri"){
        showFeedback(r.unknown?"unknown":"retry",`${state.questionRetries}回目：${badPositions}を直そう`,"赤く光っている送りがなだけを見直そう。");
      }else if(missingText){
        showFeedback("retry",`${state.questionRetries}回目：足りない線を書こう`,missingText);
      }else if(r.unknown){
        showFeedback("unknown",`${state.questionRetries}回目：${badPositions}を見てみよう`,"正解にはしていません。赤い○と説明が出ている線を、お手本とくらべて直そう。");
      }else{
        showFeedback("retry",`${state.questionRetries}回目：${badPositions}を直そう`,`赤い○と説明が出ている場所を直そう。線の長さ・向き・位置を、お手本とくらべてみよう。`);
      }
    }
  }catch(e){console.error(e);showFeedback("unknown","判定できませんでした","もう一度ためしてね。")}finally{state.checking=false;$("#aiModal").classList.add("hidden");renderHomeStats();if(!state.questionCompleted)updateCheckButton()}
};
addEventListener("resize",()=>state.boxes.forEach(resizeBox));init();

